using System;using System.Linq;using System.IO;using UnityEngine;using UnityEngine.Tilemaps;using UnityEngine.Rendering.Universal;using UnityEditor;using UnityEditor.SceneManagement;
public static class PolishGrove {
 static Sprite S(string p,string n)=>AssetDatabase.LoadAllAssetsAtPath(p).OfType<Sprite>().First(s=>s.name==n);
 static string Pond="Assets/PixelCrawler/Environment/HiddenPondClearing/";
 public static string Main(){if(Application.isPlaying)throw new Exception("Edit only");var root=GameObject.Find("EnvironmentExpansion/DrownedGrove");var enc=root.GetComponent<AshenFrontierEncounterController>();var lit=AssetDatabase.LoadAssetAtPath<Material>("Assets/Materials/ForestDayNightLit.mat");
 // Preserve the working opening animation overrides from the existing outpost chest.
 var source=GameObject.Find("Chest_Ruins");var chestPrefab=PrefabUtility.SaveAsPrefabAsset(UnityEngine.Object.Instantiate(source),"Assets/DrownedGrove/Prefabs/GroveLootChest.prefab");
 var temp=GameObject.Find("Chest_Ruins(Clone)");if(temp)UnityEngine.Object.DestroyImmediate(temp);
 foreach(var old in enc.chests){var pos=old.transform.position;var name=old.name;var g=(GameObject)PrefabUtility.InstantiatePrefab(chestPrefab,root.transform.Find("Loot"));g.name=name;g.transform.position=pos;UnityEngine.Object.DestroyImmediate(old.gameObject);}
 enc.chests=root.GetComponentsInChildren<LootChest>();
 var altar=root.transform.Find("SunkenShrine/Moss Altar");UnityEngine.Object.DestroyImmediate(altar.gameObject);
 var stone=S(Pond+"BuildingProps.png","RestWellStone");
 for(int x=0;x<3;x++)for(int y=0;y<2;y++){var g=new GameObject("Altar Moss Stone "+x+"-"+y);g.transform.SetParent(root.transform.Find("SunkenShrine"));g.transform.position=new Vector3(-12.5f+x*.5f,12.25f+y*.25f,0);var r=g.AddComponent<SpriteRenderer>();r.sprite=stone;r.sharedMaterial=lit;r.sortingLayerName="Objects";r.spriteSortPoint=SpriteSortPoint.Pivot;r.color=new Color(.7f,.87f,.8f);var c=g.AddComponent<BoxCollider2D>();c.size=new Vector2(.45f,.2f);}
 var water=GameObject.Find("Grid/HiddenPondClearing/Water/Water").GetComponent<Tilemap>();var obj=new GameObject("Deep Teal Channels");obj.transform.SetParent(root.transform.Find("Tilemaps"),false);var tm=obj.AddComponent<Tilemap>();var renderer=obj.AddComponent<TilemapRenderer>();renderer.sortingLayerName="Ground";renderer.sortingOrder=3;renderer.sharedMaterial=lit;tm.color=new Color(.50f,.78f,.77f,.72f);var tile=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<Tile>("Assets/ForestTiles/HiddenPondPlateau/WaterSolid.asset"));tile.name="GroveWaterTint";tile.colliderType=Tile.ColliderType.None;AssetDatabase.CreateAsset(tile,"Assets/DrownedGrove/GroveWaterTint.asset");
 foreach(var c in water.cellBounds.allPositionsWithin){var p=water.GetCellCenterWorld(c);if(p.x>=-30&&p.x<=-9&&p.y>=4&&p.y<=24&&water.GetColliderType(c)==Tile.ColliderType.Grid)tm.SetTile(c,tile);}
 // Walkable stepping-stone accents stay on existing land. They never imply water is safe.
 var pebble=S(Pond+"Decor.png","Rock");for(int i=0;i<9;i++){var g=new GameObject("Pilgrim Stepping Stone "+i);g.transform.SetParent(root.transform.Find("SunkenShrine"));g.transform.position=new Vector3(-12+(i%2)*.5f,8+i*.5f,0);var r=g.AddComponent<SpriteRenderer>();r.sprite=pebble;r.sharedMaterial=lit;r.sortingLayerName="Ground";r.sortingOrder=10;r.color=new Color(.72f,.86f,.82f);}
 // Two small built-in particle systems: sparse low-opacity mist, not a full-screen effect.
 var smoke=AssetDatabase.LoadAllAssetsAtPath("Assets/PixelCrawler/Bonfire/Smoke-Sheet.png").OfType<Sprite>().OrderBy(s=>s.rect.x).First();var mat=new Material(Shader.Find("Sprites/Default"));mat.name="Grove Mist";mat.mainTexture=smoke.texture;AssetDatabase.CreateAsset(mat,"Assets/DrownedGrove/GroveMist.mat");
 foreach(var p in new[]{new Vector3(-19,10,0),new Vector3(-18.5f,23,0)}){var g=new GameObject("Quiet Water Mist");g.transform.SetParent(root.transform.Find("Decorations"));g.transform.position=p;var ps=g.AddComponent<ParticleSystem>();ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=ps.main;main.duration=7;main.loop=true;main.startLifetime=5;main.startSpeed=.12f;main.startSize=new ParticleSystem.MinMaxCurve(.7f,1.3f);main.startColor=new Color(.6f,.87f,.82f,.12f);main.maxParticles=10;main.simulationSpace=ParticleSystemSimulationSpace.World;main.gravityModifier=0;var em=ps.emission;em.rateOverTime=1.5f;var shape=ps.shape;shape.shapeType=ParticleSystemShapeType.Circle;shape.radius=1;var anim=ps.textureSheetAnimation;anim.enabled=true;anim.mode=ParticleSystemAnimationMode.Sprites;anim.AddSprite(smoke);var pr=ps.GetComponent<ParticleSystemRenderer>();pr.sharedMaterial=mat;pr.sortingLayerName="Foreground";pr.sortingOrder=-5;}
 enc.tilemaps=root.GetComponentsInChildren<Tilemap>();EditorUtility.SetDirty(enc);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(root.scene);EditorSceneManager.SaveScene(root.scene);var sv=SceneView.lastActiveSceneView;sv.in2DMode=true;sv.LookAt(new Vector3(-21,14,0),Quaternion.identity,16,true,true);return "Four animated chest instances, moss stone altar, local teal channel overlay, safe stepping stones and two sparse mist systems saved.";
 }
}
